const body = $input.first().json.body ?? $input.first().json;

const raw_text = body.raw_text || '';
const client_id = body.client_id || 'test-client';
const filename = body.filename || 'manual-test.txt';

if (!raw_text) {
  throw new Error('raw_text is required');
}

// Inline default test config - replace with your real values when testing.
const clientConfig = {
  client_id,
  thresholds: { min_text_length: 50, classify_min_confidence: 0.7, extract_min_confidence: 0.8 },
  destinations: {
    invoices: { spreadsheet_id: '1JxBDiQbPqP4_9VYIatAhNldQX30Hpz_rwjr7BfK9Odo', tab: 'invoices', review_tab: 'review_queue' },
    contracts: { database_id: '096266c29be944d5958fc59e08c99605' }
  },
  forms: { destination: { kind: 'sheets', spreadsheet_id: '1JxBDiQbPqP4_9VYIatAhNldQX30Hpz_rwjr7BfK9Odo', tab: 'forms' }, fields: [] },
  telegram: { chat_id: 'REPLACE_WITH_TELEGRAM_CHAT_ID' }
};

const envelope = {
  doc_id: crypto.randomUUID(),
  received_at: new Date().toISOString(),
  source: 'manual',
  source_meta: {
    email_id: null,
    email_from: null,
    drive_file_id: null,
    drive_file_link: null,
    filename
  },
  client_id,
  client_config: clientConfig,
  raw_text
};

return [{ json: envelope }];

const env = $input.first().json;
env.review_reason = 'low_text';
env.review_details = 'Raw text length below threshold (' + (env.raw_text || '').length + ' chars).';
return [{ json: env }];

// Return a structured response to the webhook caller so they can see what happened.
const result = $input.first().json;
return [{
  json: {
    status: 'ok',
    doc_id: result.doc_id,
    type: result.type ?? null,
    type_confidence: result.type_confidence ?? null,
    extraction_confidence: result.extraction_confidence ?? null,
    validation: result.validation ?? null,
    destination: result.destination ?? null,
    review_reason: result.review_reason ?? null
  }
}];
